url = "https://www.invoka.com.ec/api/credito/emision"
headers = {
    "Content-Type": "application/json",
    "X-API-KEY": "tu-api-key-aqui"
}

try:
    response = requests.post(url, headers=headers, json=nota_credito_data)
    response.raise_for_status()

    data = response.json()

    if data.get("creado"):
        print(f"Nota de crédito creada exitosamente:")
        print(f"Clave de acceso: {data[\"claveacceso\"]}")
        print(f"ID Comprobante: {data[\"id_comprobante\"]}")
    else:
        print(f"Error en la emisión:")
        if \"errors\" in data:
            print("Detalles del error:")
            print(json.dumps(data[\"errors\"], indent=2))

except requests.exceptions.RequestException as e:
    print(f"Error de conexión: {e}")
except json.JSONDecodeError as e:
    print(f"Error al decodificar respuesta: {e}")

